function d = bpfft(v,rate,fo,f1)% function d = bpfft(v,rate,fo,f1)% bandpass fft rows of matrix v.  v is sampled at rate (Hz)% The pass band is fo < f < f1.% mod. 1-19-92, B.R. to take col vectors instead of rows.% mod. 13 dec 94, B.R. fixed bug in indexing that messed up % values at the endpts slightlyn = length(v);ffo = round(fo * n / rate);ff1 = round(f1 * n / rate);fb = fft(v);if fo == 0,  ffo = -1;end;fb([1:ffo+1 ff1+1:n-ff1+1 n-ffo+1:n],:) = ...     zeros(size(fb([1:ffo+1 ff1+1:n-ff1+1 n-ffo+1:n],:)));d = real(ifft(fb));